// Derived from the user-supplied Meshy elephant. See provenance.json.
let data;
const packed='';
export function elephantGeometryData(){
 if(!data){const s=atob(packed),bytes=new Uint8Array(s.length);for(let i=0;i<s.length;i++)bytes[i]=s.charCodeAt(i);const b=bytes.buffer;data={
  positions:new Float32Array(b,0,78273),
  normals:new Float32Array(b,313092,78273),
  uvs:new Float32Array(b,626184,52182),
  indices:new Uint16Array(b,834912,108000),
 };}
 return data;
}
